import { FC } from 'react';
import { useTranslation } from 'react-i18next';
import { FaWindows } from 'react-icons/fa';

// Generated by scripts/gen-windows-compat.mjs from the plugin Windows survey
import compat from '../../store/windows-compat.json';

export type WindowsCompatTier = 'A' | 'B' | 'C' | 'D';

export interface WindowsCompat {
  tier: WindowsCompatTier | null; // null: not in the survey
  reason: string | null;
}

interface CompatEntry {
  name: string;
  tier: WindowsCompatTier;
  reason: string;
}

const compatIds = compat.ids as Record<string, CompatEntry>;
const compatNames = compat.names as Record<string, string>;

export function isWindowsPlatform(platform: string | undefined | null): boolean {
  return platform === 'win32';
}

export function getWindowsCompat(name: string, id?: number): WindowsCompat {
  // Trust the id only while the name agrees, so testing/custom stores with other ids don't get the wrong badge
  const byId = id !== undefined ? compatIds[String(id)] : undefined;
  const byIdMatches = byId && byId.name.toLowerCase() === name.toLowerCase() ? byId : undefined;
  const nameId = compatNames[name.toLowerCase()];
  const entry = byIdMatches ?? (nameId !== undefined ? compatIds[nameId] : undefined);
  return entry ? { tier: entry.tier, reason: entry.reason } : { tier: null, reason: null };
}

const tierColors: Record<WindowsCompatTier | 'unknown', string> = {
  A: '#59bf40',
  B: '#a4d007',
  C: '#fee75c',
  D: '#ff6b6b',
  unknown: '#969696',
};

interface WindowsCompatBadgeProps {
  pluginName: string;
  pluginId?: number;
  // backend sys.platform (updater/get_version_info); the badge only renders on Windows
  platform: string | undefined | null;
  // show the reason as wrapped text instead of a single truncated line
  detailed?: boolean;
}

const WindowsCompatBadge: FC<WindowsCompatBadgeProps> = ({ pluginName, pluginId, platform, detailed }) => {
  const { t } = useTranslation();

  if (!isWindowsPlatform(platform)) return null;

  const { tier, reason } = getWindowsCompat(pluginName, pluginId);
  const color = tierColors[tier ?? 'unknown'];
  const label =
    tier === 'A'
      ? t('WindowsCompat.tier_a')
      : tier === 'B'
        ? t('WindowsCompat.tier_b')
        : tier === 'C'
          ? t('WindowsCompat.tier_c')
          : tier === 'D'
            ? t('WindowsCompat.tier_d')
            : t('WindowsCompat.untested');
  const secondary = reason ?? t('WindowsCompat.untested_desc');

  return (
    <div
      className="deckyStoreCardWindowsCompat"
      title={secondary}
      style={{
        display: 'flex',
        flexDirection: detailed ? 'column' : 'row',
        alignItems: detailed ? 'flex-start' : 'center',
        gap: detailed ? '4px' : '6px',
        minWidth: 0,
        margin: '2px 0',
      }}
    >
      <span
        className="deckyStoreCardWindowsCompatBadge"
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: '4px',
          flexShrink: 0,
          fontSize: '12px',
          fontWeight: 'bold',
          lineHeight: '16px',
          padding: '1px 6px',
          borderRadius: '3px',
          color: color,
          border: `1px solid ${color}`,
          background: `${color}22`,
          whiteSpace: 'nowrap',
        }}
      >
        <FaWindows /> {label}
      </span>
      <span
        className="deckyStoreCardWindowsCompatReason"
        style={{
          fontSize: '12px',
          color: '#969696',
          minWidth: 0,
          ...(detailed ? {} : { whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }),
        }}
      >
        {secondary}
      </span>
    </div>
  );
};

export default WindowsCompatBadge;
